#include <array>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <string>
#include <string_view>

namespace {

constexpr std::array<std::string_view, 8> patterns = {
    "agggtaaa|tttaccct",
    "[cgt]gggtaaa|tttaccc[acg]",
    "a[act]ggtaaa|tttacc[agt]t",
    "ag[act]gtaaa|tttac[agt]ct",
    "agg[act]taaa|ttta[agt]cct",
    "aggg[acg]aaa|ttt[cgt]ccct",
    "agggt[cgt]aa|tt[acg]accct",
    "agggta[cgt]a|t[acg]taccct"
};

int nucleotide(unsigned char c) {
    switch (c) {
        case 'a': return 0;
        case 'c': return 1;
        case 'g': return 2;
        case 't': return 3;
        default: return -1;
    }
}

void expand(std::string_view expression, std::size_t position,
            std::uint16_t code, std::uint8_t bit,
            std::array<std::uint8_t, 65536>& table) {
    if (position == expression.size()) {
        table[code] |= bit;
        return;
    }

    if (expression[position] == '[') {
        const std::size_t end = expression.find(']', position + 1);
        for (std::size_t i = position + 1; i < end; ++i) {
            expand(expression, end + 1,
                   static_cast<std::uint16_t>(
                       (code << 2) | nucleotide(expression[i])),
                   bit, table);
        }
    } else {
        expand(expression, position + 1,
               static_cast<std::uint16_t>(
                   (code << 2) | nucleotide(expression[position])),
               bit, table);
    }
}

std::array<std::uint64_t, 8> count_patterns(const std::string& sequence) {
    std::array<std::uint8_t, 65536> table{};
    for (std::size_t p = 0; p < patterns.size(); ++p) {
        const auto expression = patterns[p];
        const auto separator = expression.find('|');
        const auto bit = static_cast<std::uint8_t>(1u << p);
        expand(expression.substr(0, separator), 0, 0, bit, table);
        expand(expression.substr(separator + 1), 0, 0, bit, table);
    }

    std::array<std::uint64_t, 8> counts{};
    std::array<std::size_t, 8> next_start{};
    std::uint16_t code = 0;
    unsigned valid = 0;

    for (std::size_t i = 0; i < sequence.size(); ++i) {
        const int value = nucleotide(
            static_cast<unsigned char>(sequence[i]));
        if (value < 0) {
            valid = 0;
            code = 0;
            continue;
        }

        code = static_cast<std::uint16_t>((code << 2) | value);
        if (valid < 8) ++valid;
        if (valid != 8) continue;

        unsigned mask = table[code];
        if (!mask) continue;

        const std::size_t start = i - 7;
        for (unsigned p = 0; mask; ++p, mask >>= 1) {
            if ((mask & 1u) && start >= next_start[p]) {
                ++counts[p];
                next_start[p] = i + 1;
            }
        }
    }
    return counts;
}

void substitute_first(std::string& s) {
    std::size_t read = 0, write = 0;
    const std::size_t n = s.size();

    while (read < n) {
        if (n - read >= 4 &&
            s[read] == 't' && s[read + 1] == 'H' &&
            s[read + 2] == 'a' &&
            (s[read + 3] == 'N' || s[read + 3] == 't')) {
            s[write++] = '<';
            s[write++] = '4';
            s[write++] = '>';
            read += 4;
        } else {
            s[write++] = s[read++];
        }
    }
    s.resize(write);
}

void substitute_second(std::string& s) {
    std::size_t read = 0, write = 0;
    const std::size_t n = s.size();

    while (read < n) {
        bool match = false;
        if (n - read >= 3) {
            const char a = s[read];
            const char b = s[read + 1];
            const char c = s[read + 2];
            match = (a == 'a' && b == 'N' && c == 'D') ||
                    (a == 'c' && b == 'a' && c == 'N') ||
                    (a == 'H' && b == 'a' && (c == 'D' || c == 'S')) ||
                    (a == 'W' && b == 'a' && c == 'S');
        }

        if (match) {
            s[write++] = '<';
            s[write++] = '3';
            s[write++] = '>';
            read += 3;
        } else {
            s[write++] = s[read++];
        }
    }
    s.resize(write);
}

void substitute_third(std::string& s) {
    std::string result;
    result.reserve(s.size());

    for (std::size_t i = 0; i < s.size();) {
        bool match = false;
        if (s.size() - i >= 2) {
            match =
                (s[i] == 'a' &&
                 (s[i + 1] == 'N' || s[i + 1] == 'S' ||
                  s[i + 1] == 't')) ||
                (s[i] == 'B' && s[i + 1] == 'Y');
        }

        if (match) {
            result.append("<2>", 3);
            i += 2;
        } else {
            result.push_back(s[i++]);
        }
    }
    s.swap(result);
}

void substitute_tags(std::string& s) {
    std::size_t read = 0, write = 0;
    const std::size_t n = s.size();

    while (read < n) {
        if (s[read] == '<') {
            const std::size_t end = s.find('>', read + 1);
            if (end != std::string::npos) {
                s[write++] = '|';
                read = end + 1;
                continue;
            }

            while (read < n) s[write++] = s[read++];
            break;
        }
        s[write++] = s[read++];
    }
    s.resize(write);
}

std::size_t final_length(const std::string& s) {
    std::size_t result = s.size();
    std::size_t position = 0;

    while (position < s.size()) {
        const std::size_t first = s.find('|', position);
        if (first == std::string::npos) break;

        const std::size_t second = s.find('|', first + 1);
        if (second == std::string::npos) break;

        if (second == first + 1) {
            position = second;
        } else {
            result -= second - first;
            position = second + 1;
        }
    }
    return result;
}

} // namespace

int main(int argc, char** argv) {
    if (argc < 2) return 1;
    char* end = nullptr;
    const long long n = std::strtoll(argv[1], &end, 10);
    if (end == argv[1] || *end != '\0') return 1;
    (void)n;

    std::string sequence;
    std::array<char, 1 << 16> buffer;
    for (;;) {
        const std::size_t bytes =
            std::fread(buffer.data(), 1, buffer.size(), stdin);
        sequence.append(buffer.data(), bytes);
        if (bytes < buffer.size()) {
            if (std::ferror(stdin)) return 1;
            break;
        }
    }

    const std::size_t original_length = sequence.size();

    std::size_t read = 0, write = 0;
    while (read < sequence.size()) {
        if (sequence[read] == '>') {
            const std::size_t newline = sequence.find('\n', read);
            if (newline != std::string::npos) {
                read = newline + 1;
                continue;
            }
        }
        if (sequence[read] != '\n') {
            sequence[write++] = sequence[read];
        }
        ++read;
    }
    sequence.resize(write);
    const std::size_t stripped_length = sequence.size();

    const auto counts = count_patterns(sequence);

    substitute_first(sequence);
    substitute_second(sequence);
    substitute_third(sequence);
    substitute_tags(sequence);
    const std::size_t processed_length = final_length(sequence);

    for (std::size_t i = 0; i < patterns.size(); ++i) {
        std::printf("%.*s %llu\n",
                    static_cast<int>(patterns[i].size()),
                    patterns[i].data(),
                    static_cast<unsigned long long>(counts[i]));
    }
    std::printf("%zu\n%zu\n%zu\n",
                original_length, stripped_length, processed_length);
    return 0;
}

